  "installHint.chromium": "ثبّته باستخدام الأيقونة على يمين شريط العنوان، أو من قائمة المتصفح عبر «التثبيت كتطبيق».",
  "installHint.safariMac": "في Safari: قائمة ملف ← “إضافة إلى Dock”.",
  "installHint.ios": "في Safari: أيقونة المشاركة ← “إضافة إلى الشاشة الرئيسية”.",
  "installHint.firefox": "لا يستطيع Firefox تثبيت التطبيقات – لكن layerling يبدأ هنا في التبويب بدون إنترنت أيضًا.",
  "welcome.moreOfflineTitle": "يعمل بدون إنترنت",
  "welcome.moreOfflineBody": "بعد الزيارة الأولى، يبدأ layerling أيضًا بدون إنترنت - قم بتثبيته مثل أي برنامج عادي، وتبقى تصاميمك على جهازك.",
  "welcome.moreAiTitle": "البناء باستخدام الذكاء الاصطناعي",
  "welcome.moreAiBody": "عبر واجهة MCP، يستطيع مساعد ذكاء اصطناعي إنشاء الأشكال وتعديلها في محرر يفتحه بنفسه. يتطلب ذلك نسخة تشغّلها بنفسك (npm run dev، أو صورة Docker)؛ أما على layerling.com فاتصال الذكاء الاصطناعي معطّل.",
  "welcome.morePointsTitle": "النقاط المرجعية",
  "welcome.moreSearchTitle": "البحث عن الأوامر",
  "welcome.moreSimplifyTitle": "تبسيط الشبكات",
  "welcome.moreSimplifyBody": "الشبكة المستوردة ذات العدد الهائل من المثلثات تُخفَّض إلى جزء منها، مع عرض قبل وبعد وشريط تمرير - فيبقى القطع والتجميع والسحب سلسًا.",
  "welcome.moreHistoryTitle": "السجل",
  "welcome.moreLookTitle": "المظهر كما تحبه",
  "welcome.moreLookBody": "الخلفية وسطح العمل، وأسهم المحاور X وY وZ، وخطوط الحواف على كل جسم، وألوان الرسم التخطيطي، والتباين والظلال واتجاه الضوء - كلها تضبطها كما تشاء في الإعدادات، مثلًا حتى لا تختلط الأجسام الداكنة ببعضها. وعلى أجهزة الكمبيوتر الأبطأ، يوقف الوضع السريع كل ما هو مكلف دفعة واحدة.",
  "welcome.moreTabletTitle": "على الجهاز اللوحي",
  "welcome.moreTabletBody": "إصبع واحد يعمل على التصميم مثل زر الفأرة الأيسر، وإصبعان يكبّران العرض ويزيحانه؛ ولوحة مفاتيح Bluetooth تجلب الاختصارات.",
  "welcome.moreHistoryBody": "راجع أي حالة سابقة للمشروع بشريط تمرير، دون تغيير أي شيء - صدّر تلك الحالة أو ابدأ مشروعًا جديدًا منها.",
  "welcome.moreDrawingTitle": "رسم هندسي للورشة",
  "welcome.moreDrawingBody": "تصدير ← رسم هندسي: مساقط أمامية وعلوية وجانبية بمقياس 1:1 على ورقة ISO، مع الأبعاد الإجمالية والحواف المخفية وجدول للثقوب المستديرة – بصيغة PDF أو SVG، للطباعة أو لأخذه إلى المخرطة والفريزة.",
  "welcome.moreSearchBody": "اضغط Ctrl+K واكتب اسم أداة أو شكل أو أمر للانتقال إليه مباشرة - بالإنجليزية أو الألمانية، مع اختصارات لوحة المفاتيح بجانب كل منها. ويُعثر على أجسام تصميمك بأسمائها أيضًا.",
  "welcome.moreHelpTitle": "مساعدة تفاعلية",
  "welcome.moreHelpBody": "اضغط Shift+F1 أو علامة الاستفهام، ثم انقر على أي زر أو حقل أو نافذة: تعرض نافذة صغيرة الجزء الخاص به من الدليل.",
  "welcome.morePointsBody": "انقر بالزر الأيمن على جسم لتعليم مركزه أو زواياه أو منتصفات حوافه بنقاط لا تُطبع وتلتقط الأشكال إليها - ثم ضع ثقبًا تمامًا في مركز قطعة أخرى.",
  "welcome.videosTitle": "فيديوهات عن layerling",
  "welcome.videosHint": "من صنع آخرين، وليست من هذا المشروع. الروابط تفتح YouTube في تبويب جديد؛ ولا يُحمَّل أي شيء من هناك حتى تنقر.",
  "welcome.help": "في المحرر، تحتوي مجموعة المساعدة على دليل قصير وقائمة بجميع اختصارات لوحة المفاتيح. في التذييل، \"تقرير عن خطأ\" يحفظ تصميمك مع كل ما يلزم لتقرير في المنتدى أو على GitHub.",
  "welcome.guideLink": "اقرأ دليل المستخدم الكامل مع الصور",
