  "shell.errorRoundedEdges": "هذا الصندوق له حواف علوية وسفلية مستديرة، ويجب أن يكون الجدار أنحف بوضوح من ذلك التدوير. اختر جدارًا أنحف، أو اضبط تدوير الحواف العلوية والسفلية على 0 قبل تفريغه. وإذا استمر الفشل، فإن \"تقرير عن خطأ\" في التذييل يحفظ التصميم للإبلاغ.",
  "shell.errorCannotHollow": "لا يمكن تفريغ هذا الجسم، ولا حتى بجدار رقيق جدًا. على الأرجح حده الخارجي ليس نظيفًا بما يكفي لنواة CAD؛ وقد يسبب ذلك قطعٌ يلمس الحافة الخارجية، مثل فتحة باب مقطوعة حتى الحافة السفلية لشكل مستورد.",
  "shell.errorNoFlatTop": "هذا الجسم ليس له وجه علوي مسطح يمكن تركه مفتوحًا. الكرات والأشكال الحرة لا يمكن تفريغها بهذه الطريقة.",
  "shell.errorNoFlatBottom": "هذا الجسم ليس له وجه سفلي مسطح يمكن تركه مفتوحًا.",
  "edge.errorOldRevolve": "هذا الجسم الدوراني بُني كشبكة بإصدار أقدم من layerling. افتح \"تعديل الرسم التخطيطي\" وأنهِه مرة أخرى ليصبح جسمًا دقيقًا؛ بعدها يمكن تفريغه وتنعيمه وشطفه.",
