  "historyStep.offsetMany": "إزاحة {count} كائنات",
  "guide.edges.offset": "تحرّك الإزاحة كل وجه من أوجه الجسم بالمسافة نفسها، إلى الخارج أو الداخل. كبّر نسخة واحتفظ بها كثقب لتحصل على خلوص التركيب، أو صغّر جسمًا لوتد يدخل في ثقب. الأجسام التي هي شبكة مثلثات فقط يتعذّر غالبًا إزاحتها.",
  "deleteFace.title": "حذف وجه",
  "deleteFace.subtitle": "الأوجه المحيطة تسدّ الفجوة",
  "deleteFace.help": "انقر الأوجه المراد حذفها؛ ونقرة أخرى تزيل الوجه من الاختيار. تمتد الأوجه المحيطة حتى تُسدّ الفجوة: يختفي التنعيم أو الثقب أو النتوء، ويبقى الجسم دقيقًا.",
