  "deleteFace.apply": "حذف",
  "deleteFace.working": "جارٍ حذف الأوجه…",
  "deleteFace.cancel": "إلغاء حذف الأوجه",
  "deleteFace.errorUnchanged": "لا يمكن حذف هذه الأوجه: الأوجه المحيطة لا تسدّ الفجوة. اختر كل أوجه ما يجب إزالته، مثل كل أوجه التنعيم أو جدار الثقب كاملًا، ولا تختر أي وجه من الجسم نفسه.",
  "deleteFace.errorMesh": "ليس لهذا الجسم أوجه دقيقة لحذفها: يحتفظ به layerling شبكةً، مثل ملف STL أو OBJ أو 3MF مستورد، أو جسم مقسّم أو ملفوف حول أسطوانة أو مبسّط، أو شكل كثير التفاصيل كنص طويل. القطعة المستوردة بصيغة STEP لها أوجه دقيقة.",
  "deleteFace.errorResized": "تغيّر حجم هذا الجسم مع تفعيل \"الاحتفاظ بحجم الحافة عند تغيير الحجم\"، لذا لم تعد أوجهه الدقيقة تطابق حجمه. تراجع عن تغيير الحجم، واحذف الأوجه، ثم غيّر الحجم مرة أخرى.",
  "deleteFace.errorProjectChanged": "تغيّر الجسم أو المشروع أثناء حذف الأوجه؛ حاول مرة أخرى.",
  "deleteFace.errorFailed": "تعذّر حذف الأوجه. اختر أوجهًا أخرى.",
  "deleteFace.errorNoFaces": "تعذّرت قراءة أوجه هذا الجسم. أغلق الأداة وافتحها مرة أخرى.",
  "deleteFace.errorTooSlow": "استغرق حذف هذه الأوجه وقتًا طويلًا وأُوقف بعد 45 ثانية؛ لم يتغيّر شيء. لا تستطيع نواة CAD معالجة هذه الأوجه في هذه القطعة: اختر أوجهًا أخرى أو أقل.",
  "status.facesDeletedOne": "تم حذف وجه واحد",
