  "status.honeycombConverted": "تم تحويل قرص العسل إلى نمط ثقوب: {count}",
  "welcome.moreHolePatternTitle": "نمط الثقوب",
  "welcome.moreHolePatternBody": "انقر على وجه مسطح لجسم وانشر عليه الثقوب: مستديرة أو مربعة أو مستطيلة أو سداسية أو شقوقًا، في شبكة أو بترتيب متداخل، مع المسافة والهامش إلى الحافة والعمق (عبر الجسم كله أو عمق محدد). المعاينة تعرض الثقوب قبل إنشائها؛ وتبقى ثقوبًا عادية مجمّعة مع الجسم - لفتحات التهوية وشبكات مكبرات الصوت والسلال والعلب.",
  "welcome.moreFaceTitle": "دفع وجه",
  "welcome.moreFaceBody": "اسحب وجهًا مستويًا من جسم إلى الخارج أو اقطع فيه تجويفًا، مع إزاحة من الحافة وزوايا مدوّرة وعمق، بمعاينة مسبقة - وعلى ملفات STL المستوردة أيضًا.",
  "guide.select.holePattern": "نمط الثقوب (زر شريط الأدوات بجانب \"نمط\"، أو بالنقر بالزر الأيمن على جسم، أو Ctrl+K): انقر على وجه مسطح، ثم اضبط شكل الثقب وحجمه والمسافة والترتيب والهامش والعمق. تظهر الثقوب كمعاينة؛ و\"إنشاء\" يضيفها كثقوب مجمّعة مع الجسم. وفك التجميع يحررها من جديد.",
  "guide.select.faceTool": "الوجه (زر شريط الأدوات بجانب \"نمط الثقوب\"، أو بالنقر بالزر الأيمن على جسم، أو Ctrl+K): انقر على وجه مسطح، واختر للخارج أو للداخل، ثم اضبط الهامش الداخلي من الحافة ونصف قطر الزاوية والعمق. وما تضيفه الأداة هو جسم رسم تخطيطي مجمّع مع الجسم.",
  "scalePercent.errorTooSmall": "\"{name}\" سيصبح أصغر من 0.01 مم.",
