  "gear.roundHint": "أسنان مستديرة مصنوعة من أقواس، أسهل في الطباعة على التروس الصغيرة، ومسكة ناعمة على المقابض. دائرة الخطوة {pitch} مم. يتعاشق مع أي ترس مستدير الأسنان موديوله {module}؛ المسافة بين المركزين = (الأسنان + الأسنان) × الموديول / 2.",
